(async()=>{if(new URLSearchParams(location.search).get('profile')!=='upgrade-physics-check')return;const wait=ms=>new Promise(r=>setTimeout(r,ms));while(!window.EmberQA)await wait(100);const q=EmberQA,W=EmberTerrain,D=SurvivalData,U=SurvivalUpgrade,T=THREE;document.getElementById('welcome').hidden=true;q.setPlaying(false);const report=document.createElement('pre');report.id='report';report.style='position:fixed;inset:0;z-index:10000;background:white;color:#234;overflow:auto';document.body.append(report);const rows={};const check=(name,value)=>{rows[name]=value;report.textContent=JSON.stringify(rows,null,2);};
const shores=[];for(let x=-400;x<=400&&shores.length<10;x+=3)for(let z=-400;z<=400&&shores.length<10;z+=3){const h=W.ground(x,z);if(Math.abs(h-(W.water-1.5))>.06||W.inCave(x,z,h))continue;const dx=W.ground(x+.5,z)-W.ground(x-.5,z),dz=W.ground(x,z+.5)-W.ground(x,z-.5),len=Math.hypot(dx,dz);if(len<.15||len>.65||shores.some(p=>Math.hypot(p.x-x,p.z-z)<25))continue;shores.push({x,z,h,dx:dx/len,dz:dz/len});}
const results=[];for(const p of shores){q.apply({...D.fresh(),x:p.x,z:p.z,y:Math.max(p.h,W.water-1.5),yaw:Math.atan2(-p.dx,-p.dz)});q.keys({KeyW:true});for(let i=0;i<210;i++)q.move(.02);q.keys({});results.push({start:p,end:{x:q.state.x,y:q.state.y,z:q.state.z},out:!SurvivalExploration.waterAt(q.state)&&q.state.y>=W.water-.4});}check('shoreExits',results);check('allShoresExit',results.length>=5&&results.every(p=>p.out));
const l=W.landmarks.find(l=>l.kind==='temple');q.apply({...D.fresh(),x:l.x,z:l.z+14.4,y:l.y,yaw:0});q.keys({KeyW:true});let maxEye=0,prev=q.camera.position.y;for(let i=0;i<95;i++){q.move(.02);maxEye=Math.max(maxEye,Math.abs(q.camera.position.y-prev));prev=q.camera.position.y;}q.keys({});check('stairs',{z:q.state.z-l.z,height:q.state.y-l.y,maxEyeStep:maxEye,passed:q.state.z<l.z+5&&maxEye<.18});
q.apply({...D.fresh(),worldTime:360,automaticTime:false});q.sky.update(q.state,0,true);await wait(800);q.world.nativeRoot.updateWorldMatrix(true,true);const a=q.world.native.animals.find(e=>e.model.visible&&!e.rig.flying&&e.spec.scale>.5);if(a){const pos=a.model.getWorldPosition(new T.Vector3()),center=pos.clone();center.y+=a.offset||.7;Object.assign(q.state,{x:pos.x,y:pos.y,z:pos.z+2.2,inventory:{sword:1},hand:'sword'});const dir=center.clone().sub(new T.Vector3(q.state.x,q.state.y+1.4,q.state.z)).normalize();let bag;for(let n=0;n<20&&!bag;n++)U.hunt(q.world,q.state,dir,D.items.sword,25,b=>bag=b);check('hunting',{species:a.spec.id,loot:bag?.items,killed:!!bag});if(bag){q.state.bags.push(bag);q.syncObjects();check('huntingSave',D.validSave(q.snapshot()));}}
q.apply({...D.fresh(),inventory:{hammer:1,pickaxe:1},hand:'hammer'});const ore=q.world.resources.find(r=>r.kind==='ore');Object.assign(q.state,{x:ore.x,y:ore.y,z:ore.z+.8});q.interact();check('hammerCannotMine',!q.state.inventory.ore);q.assignHand(0,'pickaxe');q.interact();check('pickaxeMines',(q.state.inventory.ore||0)>0);
const homes=[];for(const h of q.world.villageHouses){q.apply({...D.fresh(),x:h.x,z:h.z+9.4,y:W.ground(h.x,h.z+9.4),yaw:0});q.keys({KeyW:true});for(let i=0;i<80;i++)q.move(.02);q.keys({});homes.push({id:h.id,entered:Math.abs(q.state.x-h.x)<1&&Math.abs(q.state.z-h.z)<2.9&&Math.abs(q.state.y-h.y-.3)<.05,wall:q.world.blocked(h.x+3.7,h.z,h.y+.3,q.state)});}check('houses',homes);check('allHouseEntries',homes.every(h=>h.entered&&h.wall));check('done',true);document.title='移動と採取の検証完了';})().catch(e=>{document.getElementById('report').textContent+='\n'+e.stack;});
